    if (ctx.reduce()) return;
    const els = [...doc.querySelectorAll('.d-head h1, .d-hero h1, .d-head .d-lede, .d-doc > h2, .d-doc section > h2')].filter(e => !e.dataset.skSplit && e.offsetParent);
